// 1. Limpiar markdown
let cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// --------
// Helper: extraer JSON balanceado
// --------
function extractBalancedJSON(text) {
  let start = text.indexOf("{");
  if (start === -1) return null;

  let depth = 0;

  for (let i = start; i < text.length; i++) {
    if (text[i] === "{") depth++;
    if (text[i] === "}") depth--;

    if (depth === 0) {
      return text.slice(start, i + 1);
    }
  }

  return null;
}

// --------
// Helper: intentar des-escape de string JSON
// --------
function tryParseEscapedJSON(text) {
  try {
    // Caso: "{ \"corrected_text\": \"...\" }"
    const unescaped = JSON.parse(text);
    if (typeof unescaped === "string") {
      return JSON.parse(unescaped);
    }
    return unescaped;
  } catch {
    return null;
  }
}

let parsed = null;

// 2. Intento directo
try {
  parsed = JSON.parse(cleaned);
} catch (_) {}

// 3. Intento des-escape
if (!parsed) {
  parsed = tryParseEscapedJSON(cleaned);
}

// 4. Intento extracción balanceada
if (!parsed) {
  const jsonString = extractBalancedJSON(cleaned);

  if (jsonString) {
    try {
      parsed = JSON.parse(jsonString);
    } catch (_) {
      parsed = tryParseEscapedJSON(jsonString);
    }
  }
}

// 5. Validación final
if (!parsed || !parsed.corrected_text) {
  throw new Error("No se pudo obtener corrected_text del LLM");
}

// 6. Output limpio
return [
  {
    json: {
      id_story: $json.id_story,
      act_number: $json.act_number,
      corrected_text: parsed.corrected_text
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  throw new Error("No hay actos corregidos");
}

// Validar y mapear
const acts = items.map(item => {

  if (!item.json.corrected_text) {
    throw new Error(`Falta corrected_text en act_number ${item.json.act_number}`);
  }

  return {
    act_number: item.json.act_number,
    corrected_text: item.json.corrected_text
  };
});

// Ordenar
acts.sort((a, b) => a.act_number - b.act_number);

// id_story
const id_story = items[0].json.id_story;

return [
  {
    json: {
      id_story,
      total_acts: acts.length,
      acts
    }
  }
];

const data = $json;

if (!data.acts || data.acts.length === 0) {
  throw new Error("No hay actos para construir full_text");
}

// Orden defensivo (por si acaso)
const acts = data.acts.sort((a, b) => a.act_number - b.act_number);

// Construcción eficiente
const full_text = acts
  .map(a => {
    if (!a.corrected_text) {
      throw new Error(`Sin corrected_text`);
    }

    return `RELATO:\n${a.corrected_text.trim()}`;
  })
  .join("\n\n");

// Output mínimo
return [
  {
    json: {   
      id_story: data.id_story,
      full_text
    }
  }
];

