const raw = $json.text || "";

// 1. Limpiar basura común
let cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// 2. Intentar parse directo
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {

  // 3. Buscar JSON interno
  const match = cleaned.match(/\{[\s\S]*\}/);

  if (!match) {
    // fallback seguro
    return [
      {
        json: {
          issues: [],
          warning: "No se pudo parsear JSON de detection"
        }
      }
    ];
  }

  try {
    parsed = JSON.parse(match[0]);
  } catch (e2) {
    return [
      {
        json: {
          issues: [],
          warning: "JSON inválido en detection"
        }
      }
    ];
  }
}

// 4. Validación estructural
if (!parsed.issues || !Array.isArray(parsed.issues)) {
  return [
    {
      json: {
        issues: [],
        warning: "No se encontraron issues válidos"
      }
    }
  ];
}

// 5. Normalización (muy importante)
const normalizedIssues = parsed.issues.map(issue => ({
  type: issue.type || "unknown",
  description: issue.description || "",
  location: issue.location || "unknown",
  severity: normalizeSeverity(issue.severity)
}));

function normalizeSeverity(sev) {
  if (!sev) return "media";

  const s = sev.toLowerCase();

  if (s.includes("alta")) return "alta";
  if (s.includes("baja")) return "baja";

  return "media";
}

// 6. Output limpio
return [
  {
    json: {
      id_story: $json.id_story,
      issues: normalizedIssues
    }
  }
];

const data = $json;

// Validaciones duras
if (!data.full_text) {
  throw new Error("Falta full_text");
}

if (!data.issues) {
  throw new Error("Faltan issues");
}

if (!data.resolution_prompt) {
  throw new Error("Falta resolution_prompt");
}

// Serializar issues (clave para el LLM)
const issuesString = JSON.stringify(data.issues, null, 2);

// Inyección en template
let prompt = data.resolution_prompt
  .replace(/{{text}}/g, data.full_text.trim())
  .replace(/{{issues}}/g, issuesString);

// Hardening fuerte (más importante que en correction)
prompt += `

IMPORTANTE:
- Responder SOLO JSON válido
- NO usar markdown
- NO agregar explicaciones
- NO incluir texto fuera del JSON
`;

// Output mínimo y limpio
return [
  {
    json: {
      id_story: data.id_story,
      prompt
    }
  }
];

const raw = $json.response || $json.text || $json.output || "";

// 1. Sanitización básica
let cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// 2. Intento de parse directo
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {

  // 3. Extraer bloque JSON (greedy pero controlado)
  const match = cleaned.match(/\{[\s\S]*\}/);

  if (!match) {
    return [
      {
        json: {
          id_story: $json.id_story,
          sanitized_text: "",
          warning: "No se encontró JSON en respuesta del LLM"
        }
      }
    ];
  }

  try {
    parsed = JSON.parse(match[0]);
  } catch (e2) {
    return [
      {
        json: {
          id_story: $json.id_story,
          sanitized_text: "",
          warning: "JSON inválido en respuesta del LLM"
        }
      }
    ];
  }
}

// 4. Validación clave
if (!parsed.sanitized_text) {
  return [
    {
      json: {
        id_story: $json.id_story,
        sanitized_text: "",
        warning: "No existe sanitized_text en la respuesta"
      }
    }
  ];
}

// 5. Limpieza final (defensiva)
let sanitized = parsed.sanitized_text.trim();

// eliminar posibles restos raros
sanitized = sanitized
  .replace(/^"+|"+$/g, "")        // comillas envolventes
  .replace(/\\n/g, "\n")          // saltos de línea escapados
  .trim();

// 6. Output final
return [
  {
    json: {
      id_story: $json.id_story,
      sanitized_text: sanitized
    }
  }
];

